    'fread', 'fwrite', 'toupper', 'tolower', 'isalpha', 'isdigit', 'isspace',
    'connect', 'socket', 'send', 'recv', 'shutdown', 'getaddrinfo', 'freeaddrinfo',
    'getsockopt', 'setsockopt', 'poll', 'bind', 'listen', 'accept', 'getpeername',
    'getsockname', 'sendto', 'recvfrom', 'sendmsg', 'recvmsg', 'closesocket',
    'ioctlsocket', 'WSAStartup', 'WSACleanup', 'WSAGetLastError', 'WSASetLastError',
